PREFIX='support_diag_20261110:'


async def save_revision(repo, key, payload):
    if await repo.setting(key):
        return
    if len(payload)<=4000:
        await repo.set_setting(key,payload)
        return
    chunks=[payload[offset:offset+3000] for offset in range(0,len(payload),3000)]
    for index,chunk in enumerate(chunks):
        await repo.set_setting(key+':part:'+str(index),chunk)
    await repo.set_setting(key,json.dumps({'format':'chunked-json','parts':len(chunks)}))


async def seed(session):
    repo=SQLRepository(session)
    async def save(model,key,title,text):
        raw=await repo.setting(PREFIX+key)
        row=await session.get(model,int(raw)) if raw and raw.isdigit() else None
        if row is None:row=await session.scalar(select(model).where(model.title==title).order_by(model.id).limit(1))
        if row is None:
            row=model(title=title,text=text,enabled=True);session.add(row);await session.flush()
        elif row.text!=text:
            revision=str(getattr(row,'version',1))
            backup=PREFIX+'previous:'+key+':'+revision
            await save_revision(repo,backup,json.dumps({'text':row.text,'title':row.title,'enabled':row.enabled},ensure_ascii=False))
            row.text=text;row.enabled=True
            if isinstance(row,AIKnowledge):row.version+=1;row.updated_at=now()
        await repo.set_setting(PREFIX+key,str(row.id))
    await save(AIKnowledge,'disconnect','VPN отключается через несколько секунд',DISCONNECT)
    title='Установка VPN-приложений: iPhone, Android и смена региона'
    row=await session.scalar(select(AIKnowledge).where(AIKnowledge.title==title).order_by(AIKnowledge.id).limit(1))
    original=row.text.split('\n\n[Проверки перед добавлением и обновлением подписки]')[0] if row else ''
    await save(AIKnowledge,'setup',title,original+'\n\n'+SETUP_NOTES)
    await save(WebQuickReply,'disconnect_reply','VPN быстро отключается: первые шаги',QUICK_CHECK)
    await save(WebQuickReply,'refresh_reply','Подписка добавлена, но не работает',QUICK_REFRESH)
    await save(AIKnowledge,'diagnostics','VPN не работает или медленно работает: диагностика по скриншоту',DIAGNOSTICS)
    await save(WebQuickReply,'screenshot_reply','Скриншот VPN-приложения',SCREENSHOT)
    await save(WebQuickReply,'speed_reply','Замер скорости без VPN',SPEED+'\n\nhttps://yandex.ru/internet/')


